<span class="line"><span style="color:#6F42C1;">Number</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;0b11&quot;</span><span style="color:#24292E;">)    </span><span style="color:#6A737D;">// 3</span></span>
